Here's a pytest test suite for `slugify`. I've written tests that pin down the function's actual behavior, including its edge cases and limitations (it doesn't collapse repeated spaces, strip whitespace, or remove punctuation).

```python
import pytest
from your_module import slugify  # adjust import to where slugify lives


class TestSlugifyBasics:
    def test_lowercases_input(self):
        assert slugify("HELLO") == "hello"

    def test_replaces_single_space_with_hyphen(self):
        assert slugify("hello world") == "hello-world"

    def test_lowercases_and_replaces(self):
        assert slugify("Hello World") == "hello-world"

    def test_multiple_words(self):
        assert slugify("The Quick Brown Fox") == "the-quick-brown-fox"

    def test_no_spaces_unchanged_except_case(self):
        assert slugify("AlreadySlugged") == "alreadyslugged"

    def test_already_slugified_is_unchanged(self):
        assert slugify("already-a-slug") == "already-a-slug"


class TestSlugifyEdgeCases:
    def test_empty_string(self):
        assert slugify("") == ""

    def test_single_space(self):
        assert slugify(" ") == "-"

    def test_leading_space(self):
        assert slugify(" hello") == "-hello"

    def test_trailing_space(self):
        assert slugify("hello ") == "hello-"

    def test_multiple_consecutive_spaces_not_collapsed(self):
        # Documents current behavior: each space becomes its own hyphen.
        assert slugify("hello  world") == "hello--world"

    def test_only_spaces(self):
        assert slugify("   ") == "---"

    def test_numbers_preserved(self):
        assert slugify("Version 2 Release 10") == "version-2-release-10"

    def test_punctuation_preserved(self):
        # Documents current behavior: punctuation is NOT stripped.
        assert slugify("Hello, World!") == "hello,-world!"

    def test_unicode_lowercased(self):
        assert slugify("CAFÉ") == "café"

    def test_tabs_and_newlines_not_replaced(self):
        # Only literal spaces are replaced, not other whitespace.
        assert slugify("hello\tworld") == "hello\tworld"
        assert slugify("hello\nworld") == "hello\nworld"


@pytest.mark.parametrize(
    "raw, expected",
    [
        ("Hello World", "hello-world"),
        ("HELLO", "hello"),
        ("", ""),
        ("a b c", "a-b-c"),
        ("  leading", "--leading"),
        ("trailing  ", "trailing--"),
        ("Mixed CASE 123", "mixed-case-123"),
    ],
)
def test_slugify_parametrized(raw, expected):
    assert slugify(raw) == expected


def test_idempotent_after_first_pass():
    # Once spaces are gone, re-slugifying changes nothing.
    once = slugify("Hello  World")
    assert slugify(once) == once
```

A few notes:

- **Import path**: change `from your_module import slugify` to wherever the function is defined.
- **Behavior-documenting tests**: `test_multiple_consecutive_spaces_not_collapsed`, `test_punctuation_preserved`, and `test_tabs_and_newlines_not_replaced` intentionally assert the *current* (arguably buggy) behavior. If you later improve `slugify` to collapse whitespace or strip punctuation, these tests will fail — which is exactly the signal you want, so update them alongside the fix.
- **`test_idempotent_after_first_pass`** captures a useful property: the function is stable once spaces are removed.

If you'd like, I can also add a stricter "ideal slug" test set (collapsing spaces, stripping punctuation, trimming hyphens) to drive a more robust implementation.
